def basis_checks(D, wanted):
    """rows (#, check, result, section) of the checks of the earlier sections of 7+1.nb whose results this document quotes; wanted is a
    list of (data key, beginning of the check name); every entry must match at least one check (a renamed check stops the build)"""
    rows = []
    for key, pre in wanted:
        hits = [c for c in D['checks'].get(key, []) if c[0].startswith(pre)]
        if not hits:
            raise ValueError('no check of %s begins with %r' % (key, pre))
        for c in hits:
            sub = (c[3] or '').strip()
            rows.append([str(len(rows) + 1), '`' + c[0].replace('`', "'") + '`', c[1], sub.split(' ')[0] if sub else c[2].split('.')[0]])
    return rows


