def _orbit_size(vec_text):
    v = [abs(int(t)) for t in vec_text.strip('()').split(',')]
    from math import factorial
    from collections import Counter
    perms = factorial(4)
    for c in Counter(v).values():
        perms //= factorial(c)
    return perms*2**sum(1 for t in v if t)


def _orbit_lists(D):
    """orbit sizes per shell k = 1..12 from the notebook output (nested list printed by section 25.1)"""
    raw = D['nums'].get('tb', {}).get(C.NB['orbits'], '')
    import re
    groups = re.findall(r'\{([0-9,\s]+)\}', raw)
    out = {}
    for k, gtxt in enumerate(groups, start=1):
        out[k] = [int(x) for x in gtxt.split(',') if x.strip()]
    return out
